alter policy "members upload product images" on storage.objects with check (bucket_id = 'product-images' and exists (select 1 from public.businesses b where b.id::text = (storage.foldername(storage.objects.name))[1] and private.user_can_manage(b.id)));
alter policy "members replace product images" on storage.objects using (bucket_id = 'product-images' and exists (select 1 from public.businesses b where b.id::text = (storage.foldername(storage.objects.name))[1] and private.user_can_manage(b.id))) with check (bucket_id = 'product-images' and exists (select 1 from public.businesses b where b.id::text = (storage.foldername(storage.objects.name))[1] and private.user_can_manage(b.id)));
alter policy "members delete product images" on storage.objects using (bucket_id = 'product-images' and exists (select 1 from public.businesses b where b.id::text = (storage.foldername(storage.objects.name))[1] and private.user_can_manage(b.id)));